//! The Rust half of the architecture-v2 hybrid-suite vectors. The vectors
//! are generated by the TypeScript port (tools/pq-hybrid-vectors.ts); every
//! deterministic output must be reproduced here byte for byte and every
//! refusal must carry the same code.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]

use core::convert::Infallible;
use ed25519_dalek::{Signature, VerifyingKey};
use flagship_crypto::seal::{HybridSealPublicKey, HybridSealSecretKey, SealOptions};
use flagship_crypto::sig::{HybridSigningKey, HybridVerifyingKey, message};
use flagship_crypto::{key_id, open, seal, seal_with_randomness};
use flagship_protocol::parse::{encode_lower_hex, parse_lower_hex};
use flagship_protocol::{EnvelopeHeader, SuiteId};
use ml_dsa::{EncodedVerifyingKey, MlDsa65, Signature as MlSig, VerifyingKey as MlVk};
use rand_core::{TryCryptoRng, TryRng, utils};
use serde_json::Value;
use sha2::{Digest, Sha512};
use std::path::PathBuf;
use x_wing::{Decapsulate, DecapsulationKey, Decapsulator, Encapsulate, KeyExport};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

fn load(rel: &str) -> Value {
    serde_json::from_str(&std::fs::read_to_string(root().join(rel)).unwrap()).unwrap()
}

fn vectors() -> Value {
    load("packages/protocol/test-vectors/pq-hybrid/vectors.json")
}

fn h(v: &Value) -> Vec<u8> {
    parse_lower_hex(v.as_str().unwrap(), 0, 1 << 22).unwrap()
}

fn arr<const N: usize>(v: &Value) -> [u8; N] {
    <[u8; N]>::try_from(h(v).as_slice()).unwrap()
}

fn x(b: &[u8]) -> String {
    encode_lower_hex(b)
}

struct Fixed(Vec<u8>);

impl TryRng for Fixed {
    type Error = Infallible;
    fn try_next_u32(&mut self) -> Result<u32, Infallible> {
        utils::next_word_via_fill(self)
    }
    fn try_next_u64(&mut self) -> Result<u64, Infallible> {
        utils::next_word_via_fill(self)
    }
    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), Infallible> {
        let rest = self.0.split_off(dest.len());
        dest.copy_from_slice(&self.0);
        self.0 = rest;
        Ok(())
    }
}
impl TryCryptoRng for Fixed {}

#[test]
fn xwing_draft11_appendix_c() {
    let kats = load("packages/protocol/test-vectors/pq-hybrid/xwing-draft11-kats.json");
    let list = kats["vectors"].as_array().unwrap();
    assert_eq!(list.len(), 3);
    for v in list {
        let dk = DecapsulationKey::from(arr::<32>(&v["seed"]));
        assert_eq!(x(dk.as_bytes()), v["sk"].as_str().unwrap());
        let ek = dk.encapsulation_key();
        assert_eq!(x(&ek.to_bytes()), v["pk"].as_str().unwrap());
        let (ct, ss) = ek.encapsulate_with_rng(&mut Fixed(h(&v["eseed"])));
        assert_eq!(x(&ct), v["ct"].as_str().unwrap());
        assert_eq!(x(&ss), v["ss"].as_str().unwrap());
        assert_eq!(x(&dk.decapsulate(&ct)), v["ss"].as_str().unwrap());
    }
}

#[test]
fn key_ids_and_raw_kem() {
    let v = vectors();
    for k in v["keyIds"].as_array().unwrap() {
        let suite = SuiteId::from_id(u16::try_from(k["suite"].as_u64().unwrap()).unwrap()).unwrap();
        assert_eq!(
            x(&key_id(suite, &h(&k["publicKey"]))),
            k["keyId"].as_str().unwrap()
        );
    }
    for k in v["kem"].as_array().unwrap() {
        let dk = DecapsulationKey::from(arr::<32>(&k["seed"]));
        let ek = dk.encapsulation_key();
        assert_eq!(x(&ek.to_bytes()), k["publicKey"].as_str().unwrap());
        let (ct, ss) = ek.encapsulate_with_rng(&mut Fixed(h(&k["eseed"])));
        assert_eq!(x(&ct), k["enc"].as_str().unwrap());
        assert_eq!(x(&ss), k["sharedSecret"].as_str().unwrap());
    }
}

fn opt_arr<const N: usize>(v: &Value) -> Option<[u8; N]> {
    v.as_str().map(|_| arr::<N>(v))
}

fn header_from(j: &Value) -> EnvelopeHeader {
    EnvelopeHeader {
        purpose: String::from(j["purpose"].as_str().unwrap()),
        suite: SuiteId::from_id(u16::try_from(j["suite"].as_u64().unwrap()).unwrap()).unwrap(),
        sender_key_id: arr(&j["senderKeyId"]),
        recipient_key_id: opt_arr(&j["recipientKeyId"]),
        installation_id: opt_arr(&j["installationId"]),
        authority_generation: j["authorityGeneration"].as_u64(),
        session_nonce: opt_arr(&j["sessionNonce"]),
        policy_digest: opt_arr(&j["policyDigest"]),
        issued_at: j["issuedAt"].as_u64().unwrap(),
        expires_at: j["expiresAt"].as_u64(),
        body_len: u32::try_from(j["bodyLen"].as_u64().unwrap()).unwrap(),
    }
}

#[test]
fn envelope_headers() {
    let v = vectors();
    for c in v["envelope"]["valid"].as_array().unwrap() {
        let hdr = header_from(&c["header"]);
        let enc = hdr.encode().unwrap();
        assert_eq!(x(&enc), c["hex"].as_str().unwrap());
        let (d, used) = EnvelopeHeader::decode_prefix(&enc).unwrap();
        assert_eq!(d, hdr);
        assert_eq!(used, enc.len());
    }
    for c in v["envelope"]["invalid"].as_array().unwrap() {
        let got = EnvelopeHeader::decode_prefix(&h(&c["hex"]))
            .map(|_| ())
            .map_err(|e| e.code());
        assert_eq!(got, Err(c["expect"].as_str().unwrap()), "{}", c["name"]);
    }
}

fn ctx_of(v: &Value) -> Vec<Vec<u8>> {
    v.as_array().unwrap().iter().map(h).collect()
}

fn refs(v: &[Vec<u8>]) -> Vec<&[u8]> {
    v.iter().map(Vec::as_slice).collect()
}

fn options_of(o: &Value) -> (String, SealOptions<'static>) {
    let purpose = String::from(o["purpose"].as_str().unwrap());
    let leaked: &'static str = Box::leak(purpose.clone().into_boxed_str());
    (
        purpose,
        SealOptions {
            purpose: leaked,
            sender_key_id: arr(&o["senderKeyId"]),
            issued_at: o["issuedAt"].as_u64().unwrap(),
            expires_at: o["expiresAt"].as_u64(),
            installation_id: opt_arr(&o["installationId"]),
            authority_generation: o["authorityGeneration"].as_u64(),
            session_nonce: opt_arr(&o["sessionNonce"]),
            policy_digest: opt_arr(&o["policyDigest"]),
        },
    )
}

#[test]
fn seal_valid_reproduces_typescript_bytes() {
    let v = vectors();
    for c in v["seal"]["valid"].as_array().unwrap() {
        let sk = HybridSealSecretKey::from_seed(&arr(&c["recipientSeed"])).unwrap();
        assert_eq!(
            x(sk.public_key().as_bytes()),
            c["recipientPublicKey"].as_str().unwrap()
        );
        assert_eq!(
            x(sk.to_seed().as_ref()),
            c["recipientSeed"].as_str().unwrap()
        );
        let ctx = ctx_of(&c["context"]);
        let (purpose, opts) = options_of(&c["options"]);
        let sealed = seal_with_randomness(
            sk.public_key(),
            &opts,
            &refs(&ctx),
            &h(&c["plaintext"]),
            &arr(&c["eseed"]),
        )
        .unwrap();
        assert_eq!(x(&sealed), c["sealed"].as_str().unwrap(), "{}", c["name"]);
        let opened = open(&sk, &purpose, &refs(&ctx), &h(&c["sealed"])).unwrap();
        assert_eq!(x(&opened.plaintext), c["plaintext"].as_str().unwrap());
        assert_eq!(opened.header.sender_key_id, opts.sender_key_id);

        let fresh = seal(sk.public_key(), &opts, &refs(&ctx), &h(&c["plaintext"])).unwrap();
        assert_ne!(fresh, sealed);
        assert_eq!(
            x(&open(&sk, &purpose, &refs(&ctx), &fresh).unwrap().plaintext),
            c["plaintext"].as_str().unwrap()
        );
    }
}

#[test]
fn seal_invalid_cases_refuse_with_the_same_code() {
    let v = vectors();
    for c in v["seal"]["invalid"].as_array().unwrap() {
        let sk = HybridSealSecretKey::from_seed(&arr(&c["recipientSeed"])).unwrap();
        let ctx = ctx_of(&c["context"]);
        let got = open(
            &sk,
            c["expectedPurpose"].as_str().unwrap(),
            &refs(&ctx),
            &h(&c["sealed"]),
        )
        .map(|_| ())
        .map_err(|e| e.code());
        assert_eq!(got, Err(c["expect"].as_str().unwrap()), "{}", c["name"]);
    }
    for c in v["seal"]["rejectPublicKeys"].as_array().unwrap() {
        let got = HybridSealPublicKey::from_bytes(&h(&c["publicKey"]))
            .map(|_| ())
            .map_err(|e| e.code());
        assert_eq!(got, Err(c["expect"].as_str().unwrap()), "{}", c["name"]);
    }
    let base = &v["seal"]["valid"][0];
    let pk = HybridSealPublicKey::from_bytes(&h(&base["recipientPublicKey"])).unwrap();
    for c in v["seal"]["rejectInputs"].as_array().unwrap() {
        let (_, mut opts) = options_of(&base["options"]);
        opts.purpose = Box::leak(String::from(c["purpose"].as_str().unwrap()).into_boxed_str());
        let n = usize::try_from(c["contextFields"].as_u64().unwrap()).unwrap();
        let ctx: Vec<&[u8]> = vec![&[]; n];
        let pt = vec![0u8; usize::try_from(c["plaintextLen"].as_u64().unwrap()).unwrap()];
        let got = seal_with_randomness(&pk, &opts, &ctx, &pt, &arr(&base["eseed"]))
            .map(|_| ())
            .map_err(|e| e.code());
        assert_eq!(got, Err(c["expect"].as_str().unwrap()), "{}", c["name"]);
    }
}

#[test]
fn sig_valid_reproduces_typescript_bytes() {
    let v = vectors();
    for c in v["sig"]["valid"].as_array().unwrap() {
        let sk = HybridSigningKey::from_seeds(&arr(&c["edSeed"]), &arr(&c["mldsaSeed"])).unwrap();
        let vk = sk.verifying_key();
        assert_eq!(x(vk.as_bytes()), c["publicKey"].as_str().unwrap());
        assert_eq!(x(&vk.key_id()), c["keyId"].as_str().unwrap());
        let purpose = c["purpose"].as_str().unwrap();
        let payload = h(&c["payload"]);
        let m = message(vk.as_bytes(), purpose, &payload).unwrap();
        assert_eq!(x(&Sha512::digest(&m)), c["messageSha512"].as_str().unwrap());
        let sig = sk.sign_deterministic(purpose, &payload).unwrap();
        assert_eq!(x(&sig), c["signature"].as_str().unwrap(), "{}", c["name"]);
        let parsed = HybridVerifyingKey::from_bytes(&h(&c["publicKey"])).unwrap();
        parsed
            .verify(purpose, &payload, &h(&c["signature"]))
            .unwrap();
        let hedged = sk.sign(purpose, &payload).unwrap();
        assert_ne!(hedged, sig);
        parsed.verify(purpose, &payload, &hedged).unwrap();
    }
}

#[test]
fn sig_invalid_cases_refuse_with_the_same_code() {
    let v = vectors();
    for c in v["sig"]["invalid"].as_array().unwrap() {
        let got = HybridVerifyingKey::from_bytes(&h(&c["publicKey"])).and_then(|vk| {
            vk.verify(
                c["purpose"].as_str().unwrap(),
                &h(&c["payload"]),
                &h(&c["signature"]),
            )
        });
        assert_eq!(
            got.map_err(|e| e.code()),
            Err(c["expect"].as_str().unwrap()),
            "{}",
            c["name"]
        );
    }
    let big = &v["sig"]["payloadTooLarge"];
    let vk = HybridVerifyingKey::from_bytes(&h(&big["publicKey"])).unwrap();
    let payload = vec![0u8; usize::try_from(big["payloadLen"].as_u64().unwrap()).unwrap()];
    let got = vk.verify(
        big["purpose"].as_str().unwrap(),
        &payload,
        &h(&big["signature"]),
    );
    assert_eq!(
        got.map_err(|e| e.code()),
        Err(big["expect"].as_str().unwrap())
    );
}

#[test]
fn stripped_components_never_verify_as_classical_only() {
    let v = vectors();
    let s = &v["sig"]["classicalStrip"];
    let pk = VerifyingKey::from_bytes(&arr(&s["publicKeyEd25519"])).unwrap();
    let sig = Signature::from_bytes(&arr(&s["signatureEd25519"]));
    assert!(pk.verify_strict(&h(&s["signedMessage"]), &sig).is_ok());
    for m in s["mustNotVerifyOver"].as_array().unwrap() {
        assert!(
            pk.verify_strict(&h(&m["message"]), &sig).is_err(),
            "{}",
            m["name"]
        );
    }
    let c = &v["sig"]["valid"][1];
    let full = h(&c["signature"]);
    let pk_all = h(&c["publicKey"]);
    let ml_pk =
        MlVk::<MlDsa65>::decode(&EncodedVerifyingKey::<MlDsa65>::try_from(&pk_all[32..]).unwrap());
    let ml_sig = MlSig::<MlDsa65>::try_from(&full[64..]).unwrap();
    let m = message(&pk_all, c["purpose"].as_str().unwrap(), &h(&c["payload"])).unwrap();
    let tag = SuiteId::HybridSigEd25519MlDsa65V1.tag().as_bytes();
    assert!(ml_pk.verify_with_context(&m, tag, &ml_sig));
    assert!(!ml_pk.verify_with_context(&m, b"", &ml_sig));
    assert!(!ml_pk.verify_with_context(&h(&c["payload"]), tag, &ml_sig));
}

fn ed_ok(pub_hex: &str, msg: &[u8], sig_hex: &str) -> bool {
    let pk = VerifyingKey::from_bytes(
        &parse_lower_hex(pub_hex, 32, 32)
            .unwrap()
            .try_into()
            .unwrap(),
    )
    .unwrap();
    let sig = Signature::from_bytes(
        &parse_lower_hex(sig_hex, 64, 64)
            .unwrap()
            .try_into()
            .unwrap(),
    );
    pk.verify_strict(msg, &sig).is_ok()
}

#[test]
fn v1_canonical_vectors_carry_valid_ed25519_signatures() {
    let f = load("test-vectors/canonical-bytes.json");
    let meta = &f["metadata"];
    let mut checked = 0;
    for vec in f["vectors"].as_array().unwrap() {
        let key = match vec["signedBy"].as_str().unwrap() {
            "irk" => "irkPubHex",
            "old-irk" => "oldIrkPubHex",
            "bak" => "bakPubHex",
            "stk" => "stkPubHex",
            "rck" => "rckPubHex",
            "identity" => "identityPubHex",
            "admin-root" => "adminRootPubHex",
            _ => continue,
        };
        let msg = h(&vec["canonicalHex"]);
        assert!(
            ed_ok(
                meta[key].as_str().unwrap(),
                &msg,
                vec["signatureHex"].as_str().unwrap()
            ),
            "{}",
            vec["name"]
        );
        checked += 1;
    }
    assert!(checked >= 34);
    for set in [
        "app-api-key",
        "llm-promo-issue",
        "backup-policy",
        "service-env-change",
    ] {
        let f = load(&format!(
            "packages/protocol/test-vectors/{set}/vectors.json"
        ));
        for c in f["cases"].as_array().unwrap() {
            let ok = ed_ok(
                f["pub"].as_str().unwrap(),
                c["canonical"].as_str().unwrap().as_bytes(),
                c["signature"].as_str().unwrap(),
            );
            assert!(ok, "{set}");
        }
    }
    let f = load("packages/protocol/test-vectors/server-order/vectors.json");
    let o = &f["order"];
    assert!(ed_ok(
        f["keys"]["irkPubHex"].as_str().unwrap(),
        o["canonical"].as_str().unwrap().as_bytes(),
        o["signatureHex"].as_str().unwrap()
    ));
}
